\section{Introduction}

\subsection{Motivation}
Smooth numbers---integers all of whose prime factors lie below a bound $y$---are the
computational substrate of sieve-based factoring and index-calculus discrete logarithms. The
running time of such an algorithm is governed by the rate at which smooth values appear in
the window being sieved, so any cheap, locally computable statistic that predicts that rate
is of direct algorithmic interest.

The cheapest such statistic is trial division by a fixed base $B$ of small primes. It
produces a set, the \emph{cell} $\cell(v)=\{p\in B: p\mid v\}$, and coarser still a single
integer, the \emph{composition order} $\kappa(v)=|\cell(v)|$.

Measurements at three bit-widths report the following.

\begin{center}
\begin{tabular}{lcccc}
\toprule
bit-width & $\kappa$-effect $\Delta$ & fitted slope (95\% CI) & identity increment & $\kappa$ sufficient?\\
\midrule
$72$ & $+0.0830$ & $-0.349\ [-0.456,-0.256]$ & $+0.0071$ & yes\\
$96$ & $+0.0869$ & $-0.380\ [-0.483,-0.279]$ & $+0.0084$ & yes\\
$128$ & $+0.0585$ & $-0.325\ [-0.432,-0.217]$ & $+0.0346$ & \textbf{no}\\
\bottomrule
\end{tabular}
\end{center}

\noindent against a pre-registered sufficiency bar of $0.02$. Three claims are made: the
effect replicates; the slope is scale-stable near $-0.35$; and the count $\kappa$ summarises
the whole cell at the two smaller scales but not at the largest.

\subsection{What this paper does}
Each claim presupposes a model. ``The slope is stable'' presupposes that a slope is a
well-defined functional of something; ``$\kappa$ is sufficient'' presupposes a distribution
over cells. We supply both exactly, and then prove what each verdict is a statement about.
The architecture separates two layers: the \emph{population layer} (how cells are distributed
among integers), computed exactly in Section~\ref{sec:period} and transferred to finite
windows in Section~\ref{sec:window}; and the \emph{response layer} (how the log-rate depends
on the cell), treated in Sections~\ref{sec:model}--\ref{sec:boundary}. The reduction that
emerges is the paper's structural message: sufficiency, scale stability and the size of the
identity increment are three faces of one property of the weight profile.

\section{The exact arithmetic cell measure}\label{sec:period}

\begin{definition}[base, period, cell, composition order]
Let $B$ be a finite set of distinct primes. Its \emph{period} is $\per(B)=\prod_{p\in B}p$.
For $v\in\N$ the \emph{cell} of $v$ is $\cell_B(v)=\{p\in B: p\mid v\}\subseteq B$ and the
\emph{composition order} is $\kappa_B(v)=|\cell_B(v)|$. For $S\subseteq B$ the \emph{cell
fibre} is $F_B(S)=\{v: 0\le v<\per(B),\ \cell_B(v)=S\}$.
\end{definition}

\begin{lemma}[fibre membership]\label{lem:memb}
For $S\subseteq B$ and any $v$, $\cell_B(v)=S$ if and only if for every $p\in B$ one has
$p\mid v \iff p\in S$.
\end{lemma}

\begin{proof}
Immediate from the definition of the cell as a filter of $B$: equality of the two finite
subsets of $B$ is exactly agreement of their membership predicates.
\end{proof}

\begin{lemma}[totient of a squarefree product]\label{lem:tot}
If $T$ is a finite set of distinct primes then
$\varphi\bigl(\prod_{p\in T}p\bigr)=\prod_{p\in T}(p-1)$.
\end{lemma}

\begin{proof}
Induction on $T$. Adjoining $a\notin T$, the prime $a$ is coprime to $\prod_{p\in T}p$
because distinct primes are coprime, so multiplicativity of $\varphi$ applies, and
$\varphi(a)=a-1$.
\end{proof}

\begin{theorem}[exact cell counts over a period]\label{thm:count}
Let $B$ be a finite base of distinct primes and $S\subseteq B$. Then
\[
|F_B(S)| \;=\; \prod_{p\in B\setminus S}(p-1).
\]
\end{theorem}

\begin{proof}
Put $d=\prod_{p\in S}p$ and $M'=\prod_{p\in B\setminus S}p$, so $\per(B)=M'd$. We show
$u\mapsto du$ is a bijection from $\{u: 0\le u<M',\ \gcd(u,M')=1\}$ onto $F_B(S)$.

\emph{Well-defined.} If $u<M'$ then $du<dM'=\per(B)$. Every $p\in S$ divides $d$, hence $du$.
For $p\in B\setminus S$ we have $p\nmid d$ (else $p$ would coincide with one of the distinct
primes of $S$) and $p\nmid u$ (since $p\mid M'$ and $\gcd(u,M')=1$), so by primality
$p\nmid du$. By Lemma~\ref{lem:memb}, $\cell(du)=S$.

\emph{Injective.} Cancel $d>0$.

\emph{Surjective.} If $\cell(v)=S$ with $v<\per(B)$ then every prime of $S$ divides $v$;
being distinct primes, their product $d$ divides $v$, say $v=du$. Then $du<dM'$ gives $u<M'$,
and $p\nmid du$ for $p\in B\setminus S$ gives $p\nmid u$; as $M'$ is squarefree with prime
divisors exactly $B\setminus S$, this yields $\gcd(u,M')=1$.

The source has cardinality $\varphi(M')=\prod_{p\in B\setminus S}(p-1)$ by Lemma~\ref{lem:tot}.
\end{proof}

\begin{remark}
A route through the Chinese Remainder Theorem stalls on identifying the component maps.
Dividing out the forced factor $d$ and invoking the totient removes the CRT entirely.
\end{remark}

\begin{theorem}[exact independence]\label{thm:indep}
For every $S\subseteq B$,
\[
\frac{|F_B(S)|}{\per(B)} \;=\; \prod_{p\in S}\frac1p \cdot \prod_{p\in B\setminus S}\Bigl(1-\frac1p\Bigr).
\]
\end{theorem}

\begin{proof}
Divide Theorem~\ref{thm:count} by $\per(B)=\bigl(\prod_{B\setminus S}p\bigr)\bigl(\prod_S p\bigr)$
and distribute: each factor $(p-1)/p$ becomes $1-1/p$ and each factor $1/p$ remains $1/p$.
\end{proof}

Thus the divisibility events $\{p\mid v\}_{p\in B}$ are exactly---not asymptotically---%
independent over a period, with marginals $1/p$.

\begin{theorem}[partition of the period]
$\sum_{S\subseteq B}|F_B(S)| = \per(B)$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:count} the sum is $\sum_S\prod_{p\in S}1\cdot\prod_{p\notin S}(p-1)$,
which by expanding $\prod_{p\in B}\bigl(1+(p-1)\bigr)=\prod_{p\in B}p$ equals $\per(B)$.
\end{proof}

\begin{theorem}[mean composition order is the truncated Mertens sum]
\[
\frac{1}{\per(B)}\sum_{v<\per(B)}\kappa_B(v) \;=\; \sum_{p\in B}\frac1p.
\]
\end{theorem}

\begin{proof}
Write $\kappa_B(v)=\sum_{p\in B}\ind[p\mid v]$ and exchange summation. For $p\in B$ we have
$p\mid\per(B)$, and $k\mapsto pk$ is a bijection from $\{0,\dots,\per(B)/p-1\}$ onto the
multiples of $p$ below $\per(B)$, so the inner count is exactly $\per(B)/p$. Divide.
\end{proof}

\begin{theorem}[every cell is populated]
$|F_B(S)|>0$ for every $S\subseteq B$.
\end{theorem}

\begin{proof}
Each factor $p-1\ge 1$ in Theorem~\ref{thm:count}.
\end{proof}

This matters for the regression: the design has support at every level $0\le\kappa\le|B|$, so
a fit on $\kappa$ is not extrapolating.

\begin{example}
For $B=\{2,3,5\}$, $\per(B)=30$ and the fibre sizes are
$\emptyset\mapsto 8$, $\{2\}\mapsto 8$, $\{3\}\mapsto 4$, $\{5\}\mapsto 2$,
$\{2,3\}\mapsto 4$, $\{2,5\}\mapsto 2$, $\{3,5\}\mapsto 1$, $\{2,3,5\}\mapsto 1$, totalling
$30$; and $8=1\cdot 2\cdot 4$, $8=2\cdot 4$, $4=1\cdot 4$, matching $\prod_{p\notin S}(p-1)$
in every case. The total of $\kappa$ over the period is $31=15+10+6$, i.e.\ mean
$31/30=\tfrac12+\tfrac13+\tfrac15$.
\end{example}

\section{From periods to windows: a certified error term}\label{sec:window}

\begin{lemma}[multiples in an initial window]\label{lem:mult}
For $d\ge 1$ and $N\ge 0$, $\#\{v<N: d\mid v\}=\lceil N/d\rceil$; hence
$\bigl|\#\{v<N:d\mid v\}-N/d\bigr|\le 1$.
\end{lemma}

\begin{proof}
The multiples are $0,d,2d,\dots$, and $dk<N$ iff $k<\lceil N/d\rceil$. The inequality is the
standard gap between a ceiling and its argument.
\end{proof}

\begin{lemma}[M\"obius expansion of the cell indicator]\label{lem:ie}
For every base $B$ of distinct primes, every $S\subseteq B$ and every integer $v$,
\[
\ind[\cell_B(v)=S] \;=\; \sum_{T\subseteq B\setminus S}(-1)^{|T|}\,
\ind\Bigl[\Bigl(\prod_{p\in S\cup T}p\Bigr)\ \Bigm|\ v\Bigr].
\]
\end{lemma}

\begin{proof}
If some $p\in S$ fails to divide $v$ then every term on the right vanishes, as does the left.
Otherwise let $E=\{p\in B\setminus S: p\mid v\}$. Since the primes are distinct, the
divisibility condition for $T$ holds precisely when $T\subseteq E$, so the sum is
$\sum_{T\subseteq E}(-1)^{|T|}=(1-1)^{|E|}$, which is $1$ if $E=\emptyset$ and $0$ otherwise.
\end{proof}

\begin{theorem}[window error bound]\label{thm:window}
For every base $B$ of distinct primes, every $S\subseteq B$ and every $N\ge 0$,
\[
\Bigl|\ \#\{v<N:\cell_B(v)=S\} \;-\; N\prod_{p\in S}\frac1p\prod_{p\in B\setminus S}\Bigl(1-\frac1p\Bigr)\ \Bigr|
\;\le\; 2^{\,|B\setminus S|}.
\]
\end{theorem}

\begin{proof}
Sum Lemma~\ref{lem:ie} over $v<N$: the count equals
$\sum_{T\subseteq B\setminus S}(-1)^{|T|}\#\{v<N: d_T\mid v\}$ with $d_T=\prod_{p\in S\cup T}p$.
Replace each count by $N/d_T$, incurring an error at most $1$ per term by
Lemma~\ref{lem:mult}. The main term is
\[
N\sum_{T\subseteq B\setminus S}\frac{(-1)^{|T|}}{\prod_{p\in S\cup T}p}
= N\prod_{p\in S}\frac1p\prod_{p\in B\setminus S}\Bigl(1-\frac1p\Bigr),
\]
by factoring out $\prod_{p\in S}p^{-1}$ and recognising the alternating sum as the expansion
of $\prod_{p\in B\setminus S}(1-1/p)$. There are $2^{|B\setminus S|}$ terms.
\end{proof}

\begin{corollary}[convergence of empirical cell frequencies]
For every $S\subseteq B$,
\[
\frac{\#\{v<N:\cell_B(v)=S\}}{N}\ \xrightarrow[\ N\to\infty\ ]{}\
\prod_{p\in S}\frac1p\prod_{p\in B\setminus S}\Bigl(1-\frac1p\Bigr).
\]
\end{corollary}

\begin{remark}
The critical feature is that the constant does not depend on $N$. Bounding the discrepancy by
the length of the incomplete final period gives a constant of order $\per(B)$, vacuous exactly
in the regime $N\ll\per(B)$ where every real experiment operates. Performing the
inclusion--exclusion \emph{before} truncating replaces $\per(B)$ by $2^{|B\setminus S|}$.
\end{remark}

\begin{example}
For $B=\{2,3,5\}$, $S=\{2\}$, the window counts at $N=10,50,97,1000$ are $3,13,26,267$ against
predicted $8N/30=2.67,13.33,25.87,266.67$; errors $0.33,0.33,0.13,0.33$ show no growth in $N$
and stay inside the proved bound $2^{|B\setminus S|}=4$.
\end{example}

\section{The additive response model and the sufficiency dichotomy}\label{sec:model}

\begin{definition}[additive log-rate]
Given a \emph{dial} $D\in\R$ and a \emph{weight profile} $w:B\to\R$, the modelled log
smoothness rate of a cell $S$ is $\Lambda(S)=D-\sum_{p\in S}w_p$.
\end{definition}

\begin{definition}[$\kappa$-sufficiency]
$\kappa$ is a \emph{sufficient statistic} for $\Lambda$ on $B$ if $|S|=|T|$ implies
$\Lambda(S)=\Lambda(T)$ for all $S,T\subseteq B$; equivalently
$\sum_{p\in S}w_p=\sum_{p\in T}w_p$.
\end{definition}

\begin{theorem}[sufficiency dichotomy]\label{thm:dichotomy}
$\kappa$ is sufficient on $B$ if and only if $w_p=w_r$ for all $p,r\in B$.
\end{theorem}

\begin{proof}
($\Rightarrow$) Apply the definition to the equinumerous singletons $\{p\}$ and $\{r\}$.
($\Leftarrow$) If $B=\emptyset$ both subsets are empty. Otherwise fix $p_0\in B$; for any
$U\subseteq B$, $\sum_{p\in U}w_p=|U|w_{p_0}$, which depends on $U$ only through $|U|$.
\end{proof}

\begin{corollary}[no intermediate regime]\label{cor:nomiddle}
For any primes $p,r$ one has $\Lambda(\{r\})-\Lambda(\{p\})=w_p-w_r$. Hence if any two
weights differ, sufficiency fails already at $\kappa=1$.
\end{corollary}

This is an informative negative result: gradedness cannot arise inside a fixed additive
model, so it must come from the scale dependence of $w$ itself. That is why the analysis
below is two-layered---weights $w$, marginals $q$, and a scale-indexed weight spread.

\begin{theorem}[a priori bound on the identity increment]\label{thm:gap}
If $m\le w_p\le M_x$ for all $p\in B$, then for $S,T\subseteq B$ with $|S|=|T|=\kappa$,
\[
|\Lambda(S)-\Lambda(T)| \;\le\; \min(\kappa,\ |B|-\kappa)\,(M_x-m).
\]
\end{theorem}

\begin{proof}
Splitting each sum over the intersection and the difference gives
$\Lambda(S)-\Lambda(T)=\sum_{p\in T\setminus S}w_p-\sum_{p\in S\setminus T}w_p$. Since
$|S|=|T|$, the differences have equal size $j=|S\setminus T|=|T\setminus S|$, and $j\le|S|=\kappa$
while $j\le|B\setminus S|=|B|-\kappa$. Bounding each sum between $jm$ and $jM_x$ gives the claim.
\end{proof}

\begin{proposition}[sharpness]
For $|B|\ge 2$ and $\kappa=1$ the bound is attained: with $S=\{p\}$, $T=\{r\}$, $w_p=M_x$,
$w_r=m$ one gets $|\Lambda(S)-\Lambda(T)|=M_x-m$.
\end{proposition}

\begin{remark}
Measuring the increment as an unconditional supremum over all pairs of cells yields the
vacuous bound $|B|(M_x-m)$. Conditioning on equal composition order recovers the sharp
constant.
\end{remark}

\section{The product cell measure and the slope law}\label{sec:slope}

\begin{definition}[product cell measure]
For marginals $q:B\to\R$ set
$P_q(S)=\prod_{p\in S}q_p\prod_{p\in B\setminus S}(1-q_p)$ and
$\E[f]=\sum_{S\subseteq B}P_q(S)f(S)$. Write $v_p=q_p(1-q_p)$.
\end{definition}

\begin{theorem}[upward marginals]\label{thm:marg}
For $T\subseteq B$, $\sum_{S\supseteq T}P_q(S)=\prod_{p\in T}q_p$; in particular
$\sum_S P_q(S)=1$, so $P_q$ is a probability distribution.
\end{theorem}

\begin{proof}
Reindex the cells containing $T$ as $S=T\cup R$ with $R\subseteq B\setminus T$. Disjointness gives
$P_q(T\cup R)=\bigl(\prod_{p\in T}q_p\bigr)\bigl(\prod_{p\in R}q_p\prod_{p\in(B\setminus T)\setminus R}(1-q_p)\bigr)$,
and the bracket sums over $R$ to $\prod_{p\in B\setminus T}\bigl(q_p+(1-q_p)\bigr)=1$. Take
$T=\emptyset$ for the second claim.
\end{proof}

\begin{corollary}[indicator moments]\label{cor:indmom}
With $\ind_p(S)=\ind[p\in S]$ one has $\E[\ind_p]=q_p$ and $\E[\ind_p\ind_r]=q_p$ if $p=r$,
$q_pq_r$ otherwise.
\end{corollary}

\begin{theorem}[moments of additive statistics]\label{thm:mom}
For $a,b:B\to\R$,
\[
\E\Bigl[\sum_{p\in S}a_p\Bigr]=\sum_{p\in B}a_pq_p, \qquad
\E\Bigl[\Bigl(\sum_{p\in S}a_p\Bigr)\Bigl(\sum_{r\in S}b_r\Bigr)\Bigr]
=\Bigl(\sum_p a_pq_p\Bigr)\Bigl(\sum_r b_rq_r\Bigr)+\sum_p a_pb_pv_p.
\]
\end{theorem}

\begin{proof}
Write $\sum_{p\in S}a_p=\sum_{p\in B}a_p\ind_p(S)$, expand the product into a double sum and
apply Corollary~\ref{cor:indmom} termwise. The off-diagonal terms reconstruct the product of
the means; the diagonal contributes $a_pb_p(q_p-q_p^2)=a_pb_pv_p$.
\end{proof}

\begin{corollary}[the four moments]\label{cor:four}
With $\kappa(S)=|S|$,
\[
\E[\kappa]=\sum_p q_p,\quad \Var(\kappa)=\sum_p v_p,\quad
\E[\Lambda]=D-\sum_p w_pq_p,\quad \Cov(\Lambda,\kappa)=-\sum_p w_pv_p,\quad \Var(\Lambda)=\sum_p w_p^2v_p.
\]
\end{corollary}

\begin{definition}[least-squares slope]
$\bols = \Cov(\Lambda,\kappa)/\Var(\kappa)$.
\end{definition}

\begin{theorem}[slope law]\label{thm:slope}
\[
\bols \;=\; \frac{-\sum_{p\in B}w_p v_p}{\sum_{p\in B}v_p}:
\]
the measured slope is exactly the $v$-weighted mean of $-w$.
\end{theorem}

\begin{proof}
Substitute the covariance and variance from Corollary~\ref{cor:four}.
\end{proof}

\begin{theorem}[scale stability equals weight homogeneity]\label{thm:stab}
If $w_p=\beta$ for all $p\in B$ and $\sum_p v_p\ne 0$, then $\bols=-\beta$---for every base
$B$, every marginal profile $q$, and hence every scale.
\end{theorem}

\begin{proof}
The numerator becomes $\beta\sum_p v_p$; cancel.
\end{proof}

\begin{theorem}[the slope identifies the weight]\label{thm:ident}
On the singleton base $B=\{p\}$ with $q_p\notin\{0,1\}$ one has $\bols=-w_p$.
\end{theorem}

Theorems~\ref{thm:stab} and \ref{thm:ident} settle the interpretation of the scale-stability
verdict: a homogeneous $w$ \emph{forces} agreement of the fitted slope at all scales with no
further hypothesis, and the slope is a faithful readout of the per-prime penalty.
Consequently, cross-scale slope stability is not additional evidence beyond the graded law;
it is equivalent to weight homogeneity.

\begin{theorem}[graded law, both directions]\label{thm:graded}
\begin{enumerate}[label=(\roman*)]
\item If $w_p=\beta$ for all $p\in B$ then $\Lambda(S)=D-\beta|S|$ for all $S\subseteq B$.
\item Conversely, if $\Lambda(S)=C-\beta|S|$ for all $S\subseteq B$, then $C=D$ and $w_p=\beta$
for every $p\in B$.
\end{enumerate}
\end{theorem}

\begin{proof}
(i) is substitution. For (ii), evaluate at $S=\emptyset$ to get $C=D$, then at $S=\{p\}$ to
get $D-w_p=D-\beta$.
\end{proof}

\begin{theorem}[the model measure is the arithmetic one]\label{thm:bridge}
If every element of $B$ is prime then, taking $q_p=1/p$, one has
$P_q(S)=|F_B(S)|/\per(B)$ for all $S\subseteq B$.
\end{theorem}

\begin{proof}
This is Theorem~\ref{thm:indep}.
\end{proof}

\begin{lemma}[nondegeneracy]\label{lem:nondeg}
If $p$ is prime then $v_p=\tfrac1p(1-\tfrac1p)>0$, since $p\ge 2$ gives $0<1/p\le 1/2$. Hence
$\sum_{p\in B}v_p>0$ for nonempty prime $B$.
\end{lemma}

\begin{theorem}[slope law over the integers]
For a nonempty base $B$ of primes with $q_p=1/p$ and constant weight $w\equiv\beta$, the
least-squares slope of the log-rate on composition order is exactly $-\beta$.
\end{theorem}

\begin{proof}
Combine Theorem~\ref{thm:stab} with Lemma~\ref{lem:nondeg}.
\end{proof}

\section{The identity increment in closed form}\label{sec:residual}

\begin{theorem}[finite Lagrange identity]\label{thm:lagrange}
For any $v,w:B\to\R$,
\[
\Bigl(\sum_p v_p\Bigr)\Bigl(\sum_p v_pw_p^2\Bigr)-\Bigl(\sum_p v_pw_p\Bigr)^2
\;=\; \tfrac12\sum_{p\in B}\sum_{r\in B}v_pv_r(w_p-w_r)^2.
\]
\end{theorem}

\begin{proof}
Expand both sides into double sums. The right-hand side is
$\tfrac12\sum_{p,r}v_pv_r(w_p^2-2w_pw_r+w_r^2)$; the two square terms are equal under the
index swap and together give $\sum_{p,r}v_pv_rw_p^2=(\sum v)(\sum vw^2)$, while the cross
term gives $-(\sum vw)^2$.
\end{proof}

\begin{corollary}[positivity and its equality case]\label{cor:pos}
If $v_p\ge 0$ on $B$ then $\sum_{p,r}v_pv_r(w_p-w_r)^2\ge 0$; if $v_p>0$ on $B$ then it
vanishes if and only if $w$ is constant on $B$.
\end{corollary}

Proving the identity first and reading positivity off it makes the equality case immediate,
whereas quoting Cauchy--Schwarz first makes it awkward.

\begin{definition}[identity increment / residual variance]
$\mathcal R = \Var(\Lambda)-\Cov(\Lambda,\kappa)^2/\Var(\kappa)$.
\end{definition}

\begin{theorem}[closed form]\label{thm:closed}
If $\sum_p v_p\ne 0$ then
\[
\mathcal R \;=\; \frac{\tfrac12\sum_{p\in B}\sum_{r\in B}v_pv_r(w_p-w_r)^2}{\sum_{p\in B}v_p},
\qquad v_p=q_p(1-q_p).
\]
\end{theorem}

\begin{proof}
By Corollary~\ref{cor:four}, $\mathcal R=\sum_p w_p^2v_p-(\sum_p w_pv_p)^2/\sum_p v_p$.
Multiply by $\sum_p v_p$ and apply Theorem~\ref{thm:lagrange}.
\end{proof}

\begin{corollary}[non-negativity]
If $v_p\ge 0$ on $B$ and $\sum_p v_p>0$ then $\mathcal R\ge 0$.
\end{corollary}

\begin{theorem}[the sufficiency law]\label{thm:suflaw}
If $v_p>0$ for all $p\in B$ and $\sum_p v_p>0$, then $\mathcal R=0$ if and only if $\kappa$
is a sufficient statistic for $\Lambda$.
\end{theorem}

\begin{proof}
Combine Theorems~\ref{thm:closed} and \ref{thm:dichotomy} with Corollary~\ref{cor:pos}.
\end{proof}

\begin{theorem}[arithmetic form]
For a nonempty base of primes with $q_p=1/p$, the exact arithmetic cell measure satisfies
$\mathcal R=0$ if and only if $\kappa$ is sufficient.
\end{theorem}

Over the integers, then, ``cell identity adds nothing beyond composition order'' is
\emph{equivalent} to weight homogeneity, with no error term and no asymptotic caveat: the
quantitative and qualitative verdicts coincide exactly.

\begin{theorem}[Popoviciu bound]\label{thm:pop}
If $v_p\ge 0$ on $B$, $\sum_p v_p>0$, and $m\le w_p\le M_x$ for all $p$, then
\[
\mathcal R \;\le\; \frac{\bigl(\sum_{p\in B}v_p\bigr)(M_x-m)^2}{4}.
\]
\end{theorem}

\begin{proof}
In the closed form each factor $(w_p-w_r)^2$ is at most $(M_x-m)^2$; the diagonal contributes
zero, and the resulting bookkeeping against the normalisation yields the constant $1/4$.
\end{proof}

\begin{theorem}[sharpness]
On a two-prime base $B=\{p,r\}$ with $q_p=q_r=1/2$,
$\mathcal R=\bigl(\sum_{x\in B}v_x\bigr)(w_p-w_r)^2/4$, so the constant $1/4$ cannot be
improved.
\end{theorem}

\begin{corollary}[certified weight spread]\label{cor:cert}
A measured increment $g>0$ forces
$M_x-m\ \ge\ 2\sqrt{g/\sum_{p\in B}v_p}$.
\end{corollary}

Corollary~\ref{cor:cert} converts a reported number into a hard statement about the model:
the $128$-bit increment $+0.0346$ cannot be produced by a nearly homogeneous weight profile.

\section{Orthogonality: why ``residual variance'' is the right name}\label{sec:ortho}

\begin{definition}[fitted line and residual]
With $\bols$ as above set $\alpha=\E[\Lambda]-\bols\E[\kappa]$ and
$R(S)=\Lambda(S)-\bigl(\alpha+\bols\kappa(S)\bigr)$.
\end{definition}

The proofs rest on bilinearity of the covariance functional of the product cell measure:
additivity in each argument, vanishing against constants, homogeneity, and symmetry, each a
direct expansion of $\E$.

\begin{theorem}[the residual is centred]
$\E[R]=0$.
\end{theorem}

\begin{proof}
$\E$ is linear and $\E[\alpha+\bols\kappa]=\alpha+\bols\E[\kappa]=\E[\Lambda]$ by the
definition of $\alpha$.
\end{proof}

\begin{theorem}[orthogonality]\label{thm:orth}
If $\Var(\kappa)\ne 0$ then $\Cov(R,\kappa)=0$.
\end{theorem}

\begin{proof}
By bilinearity $\Cov(R,\kappa)=\Cov(\Lambda,\kappa)-\bols\Var(\kappa)$, which vanishes by the
definition of $\bols$.
\end{proof}

This is precisely the property that makes the fitted line least-squares.

\begin{theorem}[the residual variance is the increment]\label{thm:varR}
If $\Var(\kappa)\ne 0$ then $\Var(R)=\mathcal R$.
\end{theorem}

\begin{proof}
Expand the right argument: $\Var(R)=\Cov(R,\Lambda)-\Cov(R,\alpha+\bols\kappa)$. The second
term vanishes by Theorem~\ref{thm:orth} and vanishing against constants; expanding the first
gives $\Var(\Lambda)-\bols\Cov(\kappa,\Lambda)=\mathcal R$.
\end{proof}

\begin{theorem}[Pythagorean decomposition]
If $\Var(\kappa)\ne 0$ then
$\Var(\Lambda)=\bols^2\Var(\kappa)+\Var(R)$, with no cross term.
\end{theorem}

\begin{corollary}[explained fraction]
If additionally $\Var(\Lambda)\ne 0$ then
\[
R^2 := \frac{\bols^2\Var(\kappa)}{\Var(\Lambda)} = 1-\frac{\mathcal R}{\Var(\Lambda)}.
\]
\end{corollary}

A reported identity increment therefore converts directly and exactly into an $R^2$
statement, the unexplained remainder being the pairwise weight-spread energy of
Theorem~\ref{thm:closed}.

\begin{example}
For $B=\{2,3,5\}$, $q_p=1/p$ and $w=(0.5,0.35,0.20)$ on $(2,3,5)$: $\E[R]=0$,
$\Cov(R,\kappa)=0$ and $\Var(R)=1017/113800\approx 0.008937$, matching
Theorem~\ref{thm:closed} exactly as a rational number. With $w\equiv 0.35$ all three vanish,
and $\E[\kappa]=31/30$, $\Var(\kappa)=569/900$, $\bols=-7/20$ exactly.
\end{example}

\section{The regime boundary of sufficiency}\label{sec:boundary}

Let $g(u)$ denote the identity increment as a function of scale $u$ and fix a bar $b$. The
\emph{verdict} at scale $u$ is the assertion $g(u)\le b$.

\begin{theorem}[downward closure]\label{thm:down}
If $g$ is monotone non-decreasing and $u_1\le u_2$, the verdict at $u_2$ implies the verdict
at $u_1$.
\end{theorem}

\begin{corollary}[no verdict reversal]
For monotone $g$ and $u_2\le u_3$, failure at $u_2$ forces failure at $u_3$. Hence a
\textsc{true}/\textsc{false}/\textsc{true} pattern across increasing scales is impossible.
\end{corollary}

This is the falsifiability content of the three-scale design: the observed pattern had a
shape it could have taken and did not.

\begin{theorem}[existence and uniqueness of the boundary]\label{thm:unique}
Let $g$ be continuous and strictly increasing on $[a,b']$ with $g(a)\le b<g(b')$. Then there
is exactly one $u^\ast\in[a,b']$ with $g(u^\ast)=b$.
\end{theorem}

\begin{proof}
Existence is the intermediate value theorem, since $b\in[g(a),g(b')]$; uniqueness is
injectivity of a strictly increasing function.
\end{proof}

\begin{theorem}[the verdict is exactly ``below the boundary'']
If $g$ is strictly increasing with $g(u^\ast)=b$, then $g(u)\le b \iff u\le u^\ast$.
\end{theorem}

\begin{theorem}[localisation of the observed boundary]\label{thm:bracket}
Suppose $g$ is continuous and strictly increasing with $g(96)=0.0084$ and $g(128)=0.0346$,
and let the bar be $0.02$. Then there is exactly one $u^\ast$ with $g(u^\ast)=0.02$, and
$u^\ast\in(96,128]$.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:unique} on $[96,128]$ using $0.0084\le 0.02<0.0346$. If $u^\ast\le 96$
then $0.02=g(u^\ast)\le g(96)=0.0084$, a contradiction, so the crossing is strictly above
$96$.
\end{proof}

\begin{theorem}[the smallest-scale verdict is forced]\label{thm:forced}
If $g$ is monotone and $g(96)=0.0084\le 0.02$, then the verdict holds at $72$ bits.
\end{theorem}

Theorem~\ref{thm:forced} is a deflation worth stating plainly: given monotonicity and the
$96$-bit measurement, the observation $g(72)=0.0071\le 0.02$ carries no independent
information about sufficiency. It is a consistency check on monotonicity, not a third data
point, and a careful accounting of evidential content must not double-count it.

\section{Algorithms}

\textbf{A. Exact cell census.} Enumerate all $2^{|B|}$ cells and return
$|F_B(S)|=\prod_{p\notin S}(p-1)$ with density $\prod_{p\in S}p^{-1}\prod_{p\notin S}(1-p^{-1})$.
Cost $O(2^{|B|}|B|)$; independent of any sampling.

\textbf{B. Window-frequency certificate.} Compute the exact window count via the
inclusion--exclusion expansion of Lemma~\ref{lem:ie} in $O(2^{|B\setminus S|})$ arithmetic
operations---no enumeration of $[0,N)$---and report the guaranteed error envelope
$2^{|B\setminus S|}$ of Theorem~\ref{thm:window}.

\textbf{C. Slope and increment evaluator.} From $q$ and $w$ compute $v_p=q_p(1-q_p)$ and
return $\bols=-\sum w_pv_p/\sum v_p$ and $\mathcal R$ by Theorem~\ref{thm:closed} in
$O(|B|^2)$ (or $O(|B|)$ via the moment form), plus the Popoviciu envelope and $R^2$.

\textbf{D. Boundary bisection.} Given a strictly increasing increment model $g$ and bar $b$,
bisect on $[a,b']$ with $g(a)\le b<g(b')$ to locate the unique crossing of
Theorem~\ref{thm:unique} in $O(\log(1/\varepsilon))$ evaluations.

\section{Applications}

\emph{Sieve triage.} Theorem~\ref{thm:window} legitimises using cell frequencies computed on
a sampled window as exact periodic densities with a stated error. With the graded law this
supports cheap triage: compute $\kappa(v)$ by trial division and prioritise small $\kappa$,
with quantified gain $e^{\beta}$ per unit of $\kappa$ avoided.

\emph{Experimental design.} Corollary~\ref{cor:cert} turns a measured increment into a lower
bound on the weight spread---the quantity a follow-up should target. Theorem~\ref{thm:ident}
identifies the cleanest measurement of an individual $w_p$. Theorem~\ref{thm:forced} shows
that a design including a scale below an already-passing scale buys nothing under
monotonicity; the budget is better spent bracketing the boundary of Theorem~\ref{thm:bracket}.

\emph{Reporting discipline.} The explained-fraction corollary makes the translation between
the identity-increment scale and the familiar $R^2$ scale exact, permitting comparison across
differently-scaled experiments without heuristic normalisation.

\section{Discussion}

The organising discovery is a reduction. Four apparently separate empirical questions are
each a question about the weight profile $w$ alone:

\begin{center}
\begin{tabular}{ll}
\toprule
Empirical question & Exact equivalent\\
\midrule
graded law $\Lambda=\text{dial}-\beta\kappa$ & $w\equiv\beta$ (Theorem~\ref{thm:graded})\\
$\kappa$ sufficient & $w$ constant (Theorem~\ref{thm:dichotomy})\\
slope stable across scales & $w$ homogeneous (Theorems~\ref{thm:slope}--\ref{thm:stab})\\
size of identity increment & pairwise spread energy of $w$ (Theorem~\ref{thm:closed})\\
\bottomrule
\end{tabular}
\end{center}

Two of these are the \emph{same} statement, which is the sharpest methodological consequence:
the scale-stability verdict and the graded-law verdict are one confirmation reported twice.
Similarly Theorem~\ref{thm:forced} shows the smallest-scale sufficiency verdict is entailed
by the middle one under monotonicity.

The main positive surprise runs the other way. Corollary~\ref{cor:nomiddle} shows that within
a fixed additive model there is no partial sufficiency: heterogeneity of any size is already
detectable at $\kappa=1$. Observed graded behaviour therefore cannot be an artefact of the
response model and must live in the scale dependence of the weights.

\emph{Limitations.} Additivity is a modelling hypothesis; interactions between small primes
are not covered. The exact counts concern initial segments of $\N$, transferred to initial
windows by Theorem~\ref{thm:window}; arbitrary offset windows follow by subtraction at the
cost of doubling the constant. The boundary results are conditional on monotonicity, and for
uniqueness on strict monotonicity and continuity of the increment in scale. The empirical
numbers are inputs to Theorems~\ref{thm:bracket}--\ref{thm:forced}, not outputs of the theory.

\section{Future work}

\textbf{A Dickman-type closed form for $\beta$.} If the log smoothness rate of a window is
asymptotically $\log\rho(u)$ with $u=\log v/\log y$ and $\rho$ the Dickman function, then
conditioning on divisibility by a small prime $p$ shifts the effective $u$ by $-\log p/\log y$.
To first order the per-prime penalty is
\[
w_p \;\approx\; -\frac{\log p}{\log y}\cdot\frac{\rho'(u)}{\rho(u)} \;=\; \frac{\log p}{\log y}\log u,
\]
a weight \emph{proportional to $\log p$}, not constant. On this account constant-$\beta$
behaviour is an artefact of a narrow base and the measured $\beta\approx-0.35$ is a
$\log$-weighted average. Theorem~\ref{thm:slope} makes this falsifiable by a single number
per scale; Theorem~\ref{thm:closed} makes it doubly falsifiable, since a $\log p$ profile
predicts a specific nonzero increment at every scale.

\textbf{Locating the boundary.} Theorem~\ref{thm:bracket} places the crossing strictly inside
$(96,128]$; measuring the increment at intermediate widths and bisecting locates it.

\textbf{Identifying the responsible cells.} Corollary~\ref{cor:cert} certifies that the
$128$-bit increment requires a definite weight spread but does not say which primes carry it;
the natural candidate is the heavy-$2$-adic direction, and the per-pair decomposition of
Theorem~\ref{thm:closed} can be audited term by term.

\textbf{Second-order response.} Adding pairwise interaction terms $w_{pr}$ and recomputing
the moments would test whether the residual, once the additive part is removed, is itself
structured.

\textbf{Arbitrary windows and correlated bases.} Extending Theorem~\ref{thm:window} to
windows at arbitrary offset with the sharp constant, and to bases including prime powers,
would remove the last gap between the exact theory and the sampling protocol.

